class Solution:
    def addBinary(self, a: str, b: str) -> str:
        # Simple, but relies on Python big integers.
        return bin(int(a, 2) + int(b, 2))[2:]

solutions.better:
class Solution:
    def addBinary(self, a: str, b: str) -> str:
        i = len(a) - 1
        j = len(b) - 1
        carry = 0
        out = []
        while i >= 0 or j >= 0 or carry:
            total = carry
            if i >= 0:
                total += ord(a[i]) - ord("0")
                i -= 1
            if j >= 0:
                total += ord(b[j]) - ord("0")
                j -= 1
            out.append(str(total & 1))
            carry = total >> 1
        return "".join(reversed(out))

